1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Circle Display</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    body {
14	      width: 100vw;
15	      height: 100vh;
16	      display: flex;
17	      justify-content: center;
18	      align-items: center;
19	      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
20	      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
21	    }
22	    svg {
23	      width: 400px;
24	      height: 400px;
25	      filter: drop-shadow(0 20px 40px rgba(0, 0, 0, 0.3));
26	    }
27	    circle {
28	      fill: #ffffff;
29	      stroke: rgba(255, 255, 255, 0.2);
30	      stroke-width: 2;
31	      transition: fill 0.3s ease;
32	    }
33	    svg:hover circle {
34	      fill: #e8f4f8;
35	    }
36	  </style>
37	</head>
38	<body>
39	  <svg id="ae683f770" viewBox="0 0 400 400">
40	    <circle cx="200" cy="200" r="200"/>
41	  </svg>
42	</body>
43	</html>
